#### C# (.NET 8+)

```csharp
// Policy interface — each rule set implements this contract
public interface IEligibilityPolicy
{
    EligibilityResult Evaluate(MemberContext member);
}

// Named policy implementation — one class per logical rule group
public sealed class MedicaidEligibilityPolicy : IEligibilityPolicy
{
    private readonly ILogger<MedicaidEligibilityPolicy> _logger;

    public MedicaidEligibilityPolicy(ILogger<MedicaidEligibilityPolicy> logger)
    {
        _logger = logger;
    }

    public EligibilityResult Evaluate(MemberContext member)
    {
        // Each condition is a named private method for readability and testability
        if (!MeetsIncomeThreshold(member))
        {
            _logger.LogInformation(
                "EligibilityPolicy={Policy} MemberRef={MemberRef} Outcome={Outcome} Reason={Reason}",
                nameof(MedicaidEligibilityPolicy), member.AnonymizedRef, "Denied", "IncomeThreshold");
            return EligibilityResult.Denied("IncomeThreshold");
        }

        if (!MeetsResidencyRequirement(member))
        {
            _logger.LogInformation(
                "EligibilityPolicy={Policy} MemberRef={MemberRef} Outcome={Outcome} Reason={Reason}",
                nameof(MedicaidEligibilityPolicy), member.AnonymizedRef, "Denied", "Residency");
            return EligibilityResult.Denied("Residency");
        }

        _logger.LogInformation(
            "EligibilityPolicy={Policy} MemberRef={MemberRef} Outcome={Outcome}",
            nameof(MedicaidEligibilityPolicy), member.AnonymizedRef, "Approved");
        return EligibilityResult.Approved();
    }

    // NOTE: Threshold values are injected via configuration — do not hard-code
    private bool MeetsIncomeThreshold(MemberContext member) =>
        member.HouseholdIncomeFpl <= member.PlanConfig.MaxIncomeFpl;

    private bool MeetsResidencyRequirement(MemberContext member) =>
        member.StateOfResidence == member.PlanConfig.StateCode;
}

// Registration in DI (Program.cs / Startup.cs)
// services.AddScoped<IEligibilityPolicy, MedicaidEligibilityPolicy>();
```

**Unit Testing (xUnit)**:

```csharp
public class MedicaidEligibilityPolicyTests
{
    [Fact]
    public void Evaluate_IncomeBelowThreshold_ReturnsApproved()
    {
        var policy = new MedicaidEligibilityPolicy(NullLogger<MedicaidEligibilityPolicy>.Instance);
        var member = MemberContextBuilder.WithIncomeFpl(130).ForState("TX").Build();
        var result = policy.Evaluate(member);
        Assert.True(result.IsApproved);
    }

    [Fact]
    public void Evaluate_IncomeAboveThreshold_ReturnsDenied()
    {
        var policy = new MedicaidEligibilityPolicy(NullLogger<MedicaidEligibilityPolicy>.Instance);
        var member = MemberContextBuilder.WithIncomeFpl(250).ForState("TX").Build();
        var result = policy.Evaluate(member);
        Assert.False(result.IsApproved);
        Assert.Equal("IncomeThreshold", result.DenialReason);
    }
}
