// Policy interface
public interface EligibilityPolicy {
    EligibilityResult evaluate(MemberContext member);
}

// Named policy implementation
@Component
public class MedicaidEligibilityPolicy implements EligibilityPolicy {

    private static final Logger log = LoggerFactory.getLogger(MedicaidEligibilityPolicy.class);

    @Override
    public EligibilityResult evaluate(MemberContext member) {
        if (!meetsIncomeThreshold(member)) {
            log.info("policy={} memberRef={} outcome=Denied reason=IncomeThreshold",
                    "MedicaidEligibilityPolicy", member.anonymizedRef());
            return EligibilityResult.denied("IncomeThreshold");
        }

        if (!meetsResidencyRequirement(member)) {
            log.info("policy={} memberRef={} outcome=Denied reason=Residency",
                    "MedicaidEligibilityPolicy", member.anonymizedRef());
            return EligibilityResult.denied("Residency");
        }

        log.info("policy={} memberRef={} outcome=Approved",
                "MedicaidEligibilityPolicy", member.anonymizedRef());
        return EligibilityResult.approved();
    }

    private boolean meetsIncomeThreshold(MemberContext member) {
        // Threshold sourced from PlanConfig — not hard-coded
        return member.householdIncomeFpl() <= member.planConfig().maxIncomeFpl();
    }

    private boolean meetsResidencyRequirement(MemberContext member) {
        return member.stateOfResidence().equals(member.planConfig().stateCode());
    }
}
