#### C# Decision Table Evaluator

```csharp
public sealed class DecisionTableEvaluator<TContext, TAction>
{
    private readonly DecisionTable<TContext, TAction> _table;
    private readonly ILogger _logger;

    public DecisionTableEvaluator(DecisionTable<TContext, TAction> table, ILogger logger)
    {
        _table = table;
        _logger = logger;
    }

    public IReadOnlyList<TAction> Evaluate(TContext context)
    {
        var matchedActions = new List<TAction>();

        foreach (var rule in _table.Rules)
        {
            if (rule.Conditions.All(c => c.IsSatisfied(context)))
            {
                _logger.LogInformation(
                    "DecisionTable={TableId} RuleId={RuleId} Description={Description} Outcome=Matched",
                    _table.TableId, rule.RuleId, rule.Description);
                matchedActions.Add(rule.Action);
            }
        }

        return matchedActions;
    }
}
```

