#### C# Rules Engine Adapter

```csharp
// Adapter wrapping the rules engine — isolates application code from vendor API
public sealed class RulesEngineAdapter
{
    private readonly IRulesEngine _engine;       // enterprise-approved engine instance
    private readonly ILogger<RulesEngineAdapter> _logger;
    private readonly IAuditLogger _auditLogger;

    public RulesEngineAdapter(
        IRulesEngine engine,
        ILogger<RulesEngineAdapter> logger,
        IAuditLogger auditLogger)
    {
        _engine = engine;
        _logger = logger;
        _auditLogger = auditLogger;
    }

    public async Task<RuleExecutionResult> ExecuteAsync(
        string workflowName,
        object input,
        CancellationToken cancellationToken = default)
    {
        var result = await _engine.ExecuteAllRulesAsync(workflowName, input);

        // Emit structured audit trace — required for regulatory compliance contexts
        foreach (var ruleResult in result.RuleResults)
        {
            _auditLogger.LogRuleExecution(new RuleExecutionTrace
            {
                WorkflowName = workflowName,
                RuleId = ruleResult.Rule.RuleName,
                IsSuccess = ruleResult.IsSuccess,
                ExceptionMessage = ruleResult.ExceptionMessage,
                InputHash = ComputeInputHash(input),   // hash, not raw PHI
                Timestamp = DateTimeOffset.UtcNow
            });
        }

        return RuleExecutionResult.FromEngineResults(result);
    }

    private static string ComputeInputHash(object input) =>
        Convert.ToHexString(SHA256.HashData(
            Encoding.UTF8.GetBytes(JsonSerializer.Serialize(input))));
}
