#### Java Rules Engine Adapter

```java
@Component
public class RulesEngineAdapter {

    private static final Logger log = LoggerFactory.getLogger(RulesEngineAdapter.class);
    private final RulesEngine engine;         // enterprise-approved engine instance
    private final AuditLogger auditLogger;

    public RulesEngineAdapter(RulesEngine engine, AuditLogger auditLogger) {
        this.engine = engine;
        this.auditLogger = auditLogger;
    }

    public RuleExecutionResult execute(String workflowName, Object input) {
        List<RuleResult> results = engine.executeAllRules(workflowName, input);

        // Emit structured audit trace
        results.forEach(result -> auditLogger.logRuleExecution(
                RuleExecutionTrace.builder()
                        .workflowName(workflowName)
                        .ruleId(result.rule().name())
                        .isSuccess(result.isSuccess())
                        .inputHash(computeInputHash(input))
                        .timestamp(Instant.now())
                        .build()));

        return RuleExecutionResult.from(results);
    }

    private String computeInputHash(Object input) {
        try {
            byte[] bytes = objectMapper.writeValueAsBytes(input);
            return HexFormat.of().formatHex(
                    MessageDigest.getInstance("SHA-256").digest(bytes));
        } catch (Exception e) {
            throw new IllegalStateException("Cannot hash rule input", e);
        }
    }
}
