export class RulesEngineAdapter {
  constructor(
    private readonly engine: RulesEngine,     // enterprise-approved engine instance
    private readonly auditLogger: AuditLogger,
    private readonly logger: Logger,
  ) {}

  async execute(workflowName: string, input: unknown): Promise<RuleExecutionResult> {
    const results = await this.engine.executeAllRules(workflowName, input);

    // Emit structured audit trace
    for (const result of results.ruleResults) {
      await this.auditLogger.logRuleExecution({
        workflowName,
        ruleId: result.rule.name,
        isSuccess: result.isSuccess,
        inputHash: this.computeInputHash(input),
        timestamp: new Date().toISOString(),
      });
    }

    return RuleExecutionResult.from(results);
  }

  private computeInputHash(input: unknown): string {
    const bytes = Buffer.from(JSON.stringify(input), 'utf8');
    return createHash('sha256').update(bytes).digest('hex');
  }
}
